\definecolor{originalBlue}{HTML}{268CFF}
\definecolor{imageRed}{HTML}{EF6068}
\draw[line width=0.25pt] (-5,-5) rectangle (5,5);
\begin{scope}
\clip (-5,-5) rectangle (5,5);
\foreach \r in {1,2,3,4,5} {\draw[line width=0.25pt] (0,0) circle (\r);}
\foreach \a in {0,30,...,330} {\draw[line width=0.25pt] (0,0)--(\a:8);}
